@libentry()
@triton.jit
def inv_kernel(A, Out, N, batch_stride, BLOCK: tl.constexpr):
    """Matrix inverse via *vectorized* Gauss-Jordan elimination with partial pivoting.

    Each program computes the inverse of one matrix in the batch. The whole
    N x N matrix is held in a BLOCK x BLOCK register tile alongside an identity
    tile, and every pivot step updates whole rows/columns at once (M <- ... ).
    This replaces the previous single-thread scalar triple loop, so the entire
    thread block cooperates on each matrix and medium/large matrices are no
    longer catastrophically slow. Padding rows/cols (index >= N) stay zero.
    """
    pid = program_id(0)
    base = pid * batch_stride

    offs = tl.arange(0, BLOCK)
    rr = offs[:, None]
    cc = offs[None, :]
    mask = (rr < N) & (cc < N)

    # Working copy of the matrix and the identity that becomes the inverse.
    W = tl.load(A + base + rr * N + cc, mask=mask, other=0.0)
    Inv = tl.where((rr == cc) & (rr < N), 1.0, 0.0).to(W.dtype)

    for col in range(N):
        # --- Partial pivoting: pick the row (>= col) with the largest |W[r, col]|.
        colvec = tl.sum(tl.where(cc == col, W, 0.0), axis=1)  # [BLOCK] = W[:, col]
        cand = tl.where((offs >= col) & (offs < N), tl.abs(colvec), -1.0)
        pmax = tl.max(cand, axis=0)
        # first row (smallest index) that attains the maximum
        prow = tl.min(tl.where(cand == pmax, offs, N), axis=0)

        # --- Swap row `col` and row `prow` in both W and Inv.
        w_row_col = tl.sum(tl.where(rr == col, W, 0.0), axis=0)  # [BLOCK]
        w_row_p = tl.sum(tl.where(rr == prow, W, 0.0), axis=0)
        i_row_col = tl.sum(tl.where(rr == col, Inv, 0.0), axis=0)
        i_row_p = tl.sum(tl.where(rr == prow, Inv, 0.0), axis=0)
        W = tl.where(rr == col, w_row_p[None, :], W)
        W = tl.where(rr == prow, w_row_col[None, :], W)
        Inv = tl.where(rr == col, i_row_p[None, :], Inv)
        Inv = tl.where(rr == prow, i_row_col[None, :], Inv)

        # --- Normalize the pivot row so that W[col, col] == 1.
        piv = tl.sum(tl.where((rr == col) & (cc == col), W, 0.0), axis=0)
        piv = tl.sum(piv, axis=0)
        prow_w = tl.sum(tl.where(rr == col, W, 0.0), axis=0) / piv
        prow_i = tl.sum(tl.where(rr == col, Inv, 0.0), axis=0) / piv
        W = tl.where(rr == col, prow_w[None, :], W)
        Inv = tl.where(rr == col, prow_i[None, :], Inv)

        # --- Eliminate the current column from every other row (vectorized).
        factor = tl.sum(tl.where(cc == col, W, 0.0), axis=1)  # [BLOCK] = W[:, col]
        factor = tl.where(offs == col, 0.0, factor)  # leave the pivot row unchanged
        W = W - factor[:, None] * prow_w[None, :]
        Inv = Inv - factor[:, None] * prow_i[None, :]

    tl.store(Out + base + rr * N + cc, Inv, mask=mask)


